import sys, json, random, copy
sys.path.insert(0, '/workspace/tmp/t')
from harness import *
import ref, gen2

def to_ref(doc):
    d = copy.deepcopy(doc)
    for tr in d['traces']:
        for e in tr['events']:
            if e['op'] == 'datagram':
                for p in e['packets']:
                    for f in p['frames']:
                        if 'data_hex' in f:
                            f['data'] = bytes.fromhex(f.pop('data_hex'))
                        if 'ranges' in f:
                            f['ranges'] = [tuple(x) for x in f['ranges']]
        for k in ('I','H','A'):
            tr['config']['sent'][k] = [tuple(x) for x in tr['config']['sent'][k]]
    return d

def norm(x):
    return json.loads(json.dumps(x, sort_keys=True))

rng = random.Random(int(sys.argv[2]))
N = int(sys.argv[1])
bad = 0
stats = {'accepted':0,'error':0,'dropped':0,'duplicate':0,'buffered':0,'streams':0,'closed':0,'idle':0,'open':0}
for it in range(N):
    doc = gen2.rand_doc(rng)
    got, _ = run(doc)
    if got == INVALID:
        print('iter', it, 'valid doc rejected!'); print(json.dumps(doc)[:3000]); bad += 1; break
    for tr in got['results']:
        for p in tr['packets']: stats[p['status']] += 1
        stats[tr['connection']['state']] += 1
        stats['streams'] += len(tr['streams'])
    rd = to_ref(doc)
    want = {'version': 1, 'results': [ref.run_trace(t['id'], t['config'], t['events']) for t in rd['traces']]}
    if norm(got) != norm(want):
        bad += 1
        print('MISMATCH iter', it)
        for i, (a, b) in enumerate(zip(got['results'], want['results'])):
            if norm(a) != norm(b):
                print('trace', i, a['id'])
                for k in a:
                    if norm(a[k]) != norm(b[k]):
                        print('  key', k)
                        print('   got :', json.dumps(a[k])[:2000])
                        print('   want:', json.dumps(b[k])[:2000])
        json.dump(doc, open('/workspace/tmp/t/reffail2.json','w'))
        if bad > 1: break
print('done iters', it + 1, 'bad', bad, stats)
